'use strict';
// 原创练习，借鉴行测判断推理的题型，不使用或宣称为官方真题。
const reasoningQuestions = [
 {id:'r1',kind:'逻辑判断',title:'充分条件：谁一定参加？',stem:'某单位规定：凡参加数据培训的员工，都要参加信息安全培训。小林没有参加信息安全培训。\n根据以上信息，可以必然推出：',options:['小林参加了数据培训','小林没有参加数据培训','小林参加了其他培训','所有参加信息安全培训的人都参加了数据培训'],answer:1,analysis:'把规定写成“数据培训 → 安全培训”。已知小林没有参加安全培训，可用逆否推理得出：小林没有参加数据培训。',explanations:['与规定及已知条件矛盾。参加数据培训就必须参加安全培训。','正确。否定后件，可以否定前件。','题干没有提供其他培训的信息。','把“如果 A，那么 B”倒置成“如果 B，那么 A”，不能必然成立。'],tip:'A → B 的逆否命题是 非 B → 非 A；不能直接反向推出 B → A。'},
 {id:'r2',kind:'逻辑判断',title:'必要条件：有权限就够了吗？',stem:'只有通过安全审核的员工，才能获得系统访问权限。小周通过了安全审核。\n以下哪项判断最准确？',options:['小周一定获得了系统访问权限','小周一定没有系统访问权限','无法仅凭上述信息确定小周是否获得权限','所有通过审核的员工都有权限'],answer:2,analysis:'“只有通过审核，才能获得权限”表示“获得权限 → 通过审核”。通过审核是必要条件，但可能还需要其他条件。已知通过审核，不能确定是否获得权限。',explanations:['把必要条件当成了充分条件。','通过审核不意味着没有权限。','正确。题干允许小周有权限，也允许没有权限。','题干没有说通过审核就自动授予权限。'],tip:'“只有 A，才 B”写成 B → A。先找箭头方向，再作推断。'},
 {id:'r3',kind:'削弱论证',title:'销量上涨，是广告的功劳吗？',stem:'某商店本月投放短视频广告后，销量比上月增长了 30%。经理据此认为，销量增长主要由短视频广告带来。\n以下哪项如果为真，最能削弱经理的结论？',options:['部分顾客喜欢看短视频','商店去年也投放过广告','制作广告需要一定费用','本月商店同时大幅降价，且新增订单大多来自降价促销入口'],answer:3,analysis:'经理从广告投放与销量上涨同时发生，推断广告是主要原因。D 提供了与新增订单直接相关的替代原因——降价促销，因此最能削弱这一因果归因。',explanations:['顾客偏好并不能解释本次销量增长的主要原因。','缺少去年效果等信息，不能直接削弱。','成本影响利润，不直接说明销量由什么带来。','正确。给出了更直接的替代原因及订单来源证据。'],tip:'遇到“做了 X，随后 Y 变好，所以是 X 导致的”，优先检查其他同时发生的变化。'},
 {id:'r4',kind:'加强论证',title:'提醒消息真的有帮助吗？',stem:'一项研究把条件相近的志愿者随机分成两组。实验组每天收到运动提醒，对照组不收到。四周后，实验组平均每周多运动 40 分钟。研究者认为，提醒有助于增加运动时间。\n以下哪项如果为真，最能加强该结论？',options:['两组在运动奖励、器材和其他指导方面相同，提醒是唯一系统性差异','多数志愿者觉得运动有益健康','提醒消息使用了清晰的字体','实验组中有一人原本就喜欢运动'],answer:0,analysis:'A 进一步排除了奖励、器材和指导等混杂因素，使两组运动时间的差异更有理由归因于提醒。',explanations:['正确。控制其他差异，增强因果解释。','健康观念不能说明提醒的实际效果。','字体清晰不等于提醒会增加运动。','一个人的偏好无法支撑整组的因果结论。'],tip:'加强因果论证时，排除其他解释、保证对照可比，通常比补充背景更有力。'},
 {id:'r5',kind:'排列推理',title:'三个人的汇报顺序',stem:'甲、乙、丙三人依次汇报，每人一次。已知：\n① 甲不排第一；\n② 乙排在丙之前；\n③ 丙不排最后。\n三人的顺序是：',options:['甲、乙、丙','乙、丙、甲','丙、乙、甲','乙、甲、丙'],answer:1,analysis:'乙在丙之前，所以丙不能第一；又因丙不排最后，丙只能第二。于是乙第一，甲第三。',explanations:['甲排第一，丙排最后，都违反条件。','正确。三个条件全部满足。','乙没有排在丙之前。','丙排最后，违反条件③。'],tip:'先找限制最集中的对象，再确定位置；把答案代回所有条件检查。'},
 {id:'r6',kind:'定义判断',title:'什么是机会成本？',stem:'在本题中，机会成本指：为选择某个方案而放弃的其他可行方案中，价值最高的那个方案所能带来的收益。\n小陈周末可选择兼职赚 300 元、做翻译赚 500 元，或去徒步。三种活动时间冲突，只能选一种。小陈最终去徒步。以本题列出的金钱收益计算，徒步的机会成本是：',options:['300 元','800 元','500 元','0 元'],answer:2,analysis:'被放弃且可行的方案有兼职和翻译，其中收益最高的是翻译的 500 元。定义要求取最大值，不是把所有放弃的收益相加。',explanations:['兼职可行，但不是价值最高的放弃方案。','不能同时做兼职和翻译，因此不能相加。','正确。放弃方案中的最高金钱收益是 500 元。','去徒步没有金钱收入，不代表放弃的收益为零。'],tip:'定义判断先圈出限定词：“其他可行方案”“价值最高”。严格按题目定义判断。'},
 {id:'r7',kind:'类比推理',title:'先认清词语之间的关系',stem:'温度计：温度\n下列哪组词语与题干关系最相似？',options:['天平：质量','尺子：木材','时钟：墙壁','地图：纸张'],answer:0,analysis:'题干是“测量工具：所测量的物理量”。天平测量质量，与题干关系一致。',explanations:['正确。工具与测量对象的物理量一一对应。','木材是材料或具体物体，尺子测量的是长度。','墙壁可能是时钟放置的位置。','纸张可能是地图的载体。'],tip:'先用一句话描述两个词的关系，再逐项代入，避免只看词语是否相关。'},
 {id:'r8',kind:'逻辑判断',title:'“有些”能推出“所有”吗？',stem:'某读书会的所有组织者都是会员，有些会员是教师。\n根据上述信息，以下哪项一定为真？',options:['所有组织者都是教师','有些组织者是教师','没有组织者是教师','有些教师是该读书会会员'],answer:3,analysis:'“有些会员是教师”说明至少存在一个人既是会员又是教师，因此可以换位为“有些教师是会员”。组织者与教师是否重合，题干没有确定。',explanations:['会员中有教师，不代表所有组织者都是教师。','有些会员是教师，但这些会员未必是组织者。','教师和组织者也可能有重合，不能断言没有。','正确。“有些 A 是 B”可推出“有些 B 是 A”。'],tip:'关注量词和集合关系。“有些”只保证至少存在一个，不能扩大成“所有”。'}
];
let reasoningFilter='全部',quiz=null;
const quizKinds=['全部',...new Set(reasoningQuestions.map(q=>q.kind))];
const baseLibrary=library,basePractice=practice,baseRoute=route;
// 使用现有 sessions 结构保存客观题记录，兼容既有成长记录和导出。
function reasoningHistory(){return state.sessions.filter(s=>s.mode==='reasoning')}
function reasoningLibrary(){const history=reasoningHistory();const correct=history.filter(s=>s.correct).length;shell(heading('Reasoning practice','把判断，建立在理由上。','参考行测判断推理题型的原创单选题。先独立作答，再看正确答案、逐项解析和解题方法。')+`<div class="note">共 ${reasoningQuestions.length} 题 · 每题四选一 · 原创练习，非官方真题</div><div class="stats"><div class="stat"><strong>${history.length}</strong><span>累计作答次数</span></div><div class="stat"><strong>${history.length?Math.round(correct/history.length*100)+'%':'—'}</strong><span>作答正确率（含重复练习）</span></div><div class="stat"><strong>${new Set(history.filter(s=>!s.correct).map(s=>s.scenarioId)).size}</strong><span>曾答错的题目</span></div></div><div class="filters">${[...quizKinds,'错题回练'].map(k=>`<button class="filter ${reasoningFilter===k?'active':''}" data-kind="${esc(k)}">${k}</button>`).join('')}</div><div class="scenario-grid">${reasoningQuestions.filter(q=>reasoningFilter==='全部'||reasoningFilter===q.kind||(reasoningFilter==='错题回练'&&history.some(h=>h.scenarioId===q.id&&!h.correct))).map(q=>{const last=history.find(h=>h.scenarioId===q.id);return `<article class="panel scenario-card"><span class="eyebrow">${q.kind} · 单选题</span><h2>${q.title}</h2><p>${q.stem.split('\n')[0]}</p><div class="card-bottom"><span class="tiny">${last?`最近一次：${last.correct?'答对':'答错'}`:'尚未作答'}</span><a class="text-button" href="#reasoning/${q.id}">${last?'再练一次':'开始答题'} ↗</a></div></article>`}).join('')||'<div class="panel empty"><h2>这里还没有错题。</h2><p>完成练习后，答错的题目会出现在这里。</p></div>'}</div>`);document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{reasoningFilter=b.dataset.kind;reasoningLibrary()})}
function reasoningPractice(id){const q=reasoningQuestions.find(q=>q.id===id);if(!q){location.hash='#library/thinking';return}if(!quiz||quiz.id!==id)quiz={id,selected:null,submitted:false};const letters=['A','B','C','D'];shell(`<div class="workspace"><a class="breadcrumb" href="#library/thinking">← 返回清晰思考题库</a>${heading(q.kind, q.title,`第 ${reasoningQuestions.indexOf(q)+1} / ${reasoningQuestions.length} 题 · 原创单选题`)}<section class="panel"><p class="question-stem">${esc(q.stem)}</p><form id="quiz-form"><fieldset class="quiz-options" ${quiz.submitted?'disabled':''}><legend class="label">选择唯一最合适的答案</legend>${q.options.map((o,i)=>`<label class="quiz-option ${quiz.submitted?(i===q.answer?'correct':i===quiz.selected?'incorrect':''):''}"><input type="radio" name="answer" value="${i}" ${quiz.selected===i?'checked':''} required><span class="option-letter">${letters[i]}</span><span>${esc(o)}</span>${quiz.submitted&&i===q.answer?'<b class="option-result">正确答案</b>':''}</label>`).join('')}</fieldset>${quiz.submitted?'':`<div class="actions"><span class="hint">提交前可修改选择。</span><button class="primary" type="submit">提交答案 →</button></div>`}</form></section>${quiz.submitted?`<section class="panel" style="margin-top:20px"><span class="pill">${quiz.selected===q.answer?'回答正确 ✓':'这次选错了，看看推理过程'}</span><h2 style="margin-top:14px">你的选择 ${letters[quiz.selected]} · 正确答案 ${letters[q.answer]}</h2><p>${q.analysis}</p>${q.explanations.map((e,i)=>`<div class="feedback-item"><div class="feedback-title">${letters[i]} · ${i===q.answer?'正确':'排除'}</div><p>${e}</p></div>`).join('')}<div class="note"><b>解题方法</b><br>${q.tip}</div><div class="actions"><button class="secondary" id="retry-quiz">重做本题</button>${reasoningQuestions.indexOf(q)<reasoningQuestions.length-1?`<a class="primary" href="#reasoning/${reasoningQuestions[reasoningQuestions.indexOf(q)+1].id}">下一题 →</a>`:'<a class="primary" href="#library/thinking">返回题库 ✓</a>'}</div></section>`:''}</div>`);document.querySelectorAll('input[name="answer"]').forEach(el=>el.onchange=()=>{quiz.selected=Number(el.value)});document.getElementById('quiz-form').onsubmit=e=>{e.preventDefault();if(quiz.submitted)return;const choice=document.querySelector('input[name="answer"]:checked');if(!choice){toast('先选择一个答案。');return}quiz.selected=Number(choice.value);quiz.submitted=true;state.sessions.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),scenarioId:q.id,type:'thinking',mode:'reasoning',title:q.title,selected:quiz.selected,correct:quiz.selected===q.answer,firstAnswer:`${letters[quiz.selected]}. ${q.options[quiz.selected]}`,retryAnswer:`正确答案：${letters[q.answer]}. ${q.options[q.answer]}`,takeaway:q.tip,action:'在现实判断中练习：'+q.tip,done:false});persist();reasoningPractice(q.id)};const retry=document.getElementById('retry-quiz');if(retry)retry.onclick=()=>{quiz=null;reasoningPractice(q.id)}}
library=function(category){if(category==='thinking')return reasoningLibrary();baseLibrary(category);if(!category){const grid=document.querySelector('.scenario-grid');for(const card of [...grid.children])if(card.querySelector('a[href="#practice/evidence"],a[href="#practice/decision"]'))card.remove();grid.insertAdjacentHTML('afterbegin',`<article class="panel scenario-card"><span class="eyebrow">清晰思考 · 判断推理</span><h2>先选答案，再拆解推理过程</h2><p>逻辑判断、加强削弱、排列推理、定义判断和类比推理。${reasoningQuestions.length} 道原创单选题，支持错题回练。</p><div class="card-bottom"><span class="tiny">四选一 · 逐项解析</span><a class="text-button" href="#library/thinking">进入推理题库 ↗</a></div></article>`)}};
practice=function(id){if(id==='evidence'||id==='decision'){location.hash='#library/thinking';return}basePractice(id)};
// 替换主页能力卡中的题量说明；其他模块继续使用情境练习。
function enhancedRoute(){const [page,id]=(location.hash||'#home').slice(1).split('/');if(page!=='reasoning')quiz=null;if(page==='reasoning'){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='library'));reasoningPractice(id);previousHash=location.hash;window.scrollTo({top:0,behavior:'instant'});return}baseRoute();const card=document.querySelector('.skill-card[href="#library/thinking"]');if(card){card.querySelector('p').textContent='行测风格单选题，练逻辑与判断';card.querySelector('.skill-foot span').textContent=`${reasoningQuestions.length} 道推理选择题`}if(page==='about'){document.querySelector('.sources').insertAdjacentHTML('afterbegin','<div class="note">清晰思考模块使用原创客观选择题，按预设正确答案判题，并提供逐项解析。题型参考行测判断推理，不是官方真题；其他模块继续使用情境练习与规则提示。</div>')}}
window.removeEventListener('hashchange',route);route=enhancedRoute;window.addEventListener('hashchange',route);route();
